const response = $input.first().json;

const estates = response?._embedded?.estates ?? [];

if (estates.length === 0) {
  return [{ json: { text: '⚠️ No results found or structure changed.' } }];
}

const typeMap     = { 1: 'Prodej', 2: 'Pronájem', 3: 'Dražba' };
const categoryMap = { 1: 'Byt', 2: 'Dům', 3: 'Pozemek', 4: 'Komerční', 5: 'Ostatní' };

const lines = estates.map(p => {
  const priceRaw = p.price_czk?.value_raw ?? p.price ?? null;
  const price    = priceRaw ? `${priceRaw.toLocaleString('cs-CZ')} Kč` : 'cena na vyžádání';

  const location       = p.locality ?? '';
  const categoryMain   = categoryMap[p.seo?.category_main_cb] ?? '';
  const transactionType = typeMap[p.seo?.category_type_cb] ?? '';
  const type           = [transactionType, categoryMain].filter(Boolean).join(' · ');

  const url = `https://www.sreality.cz${p._links?.self?.href}`;

  const featureLabels = (p.labels ?? []).slice(0, 3).join(' · ');
  const labelsLine    = featureLabels ? `\n  🏷 ${featureLabels}` : '';

  return `• *${p.name}*\n  ${type} | 📍 ${location}${labelsLine}\n  💰 ${price}\n  🔗 ${url}`;
});

const resultSize = response.result_size ?? estates.length;
const text = `🏠 *Sreality — ${resultSize} inzerátů (zobrazeno ${estates.length})*\n\n` + lines.join('\n\n');

const truncated = text.length > 4000
  ? text.slice(0, 4000) + '\n\n_(zkráceno)_'
  : text;

return [{ json: { text: truncated } }];
